import{_ as a,o as l,c as n,aw as o}from"./chunks/framework.DLufY-ao.js";const t="/workbook/assets/bubbling1.BcYyIB_V.png",g=JSON.parse('{"title":"3. Фаза всплытия","description":"","frontmatter":{},"headers":[],"relativePath":"js/js-web-api/dom-events/propagation-bubbling.md","filePath":"wiki/dev-commit/js/js-web-api/dom-events/propagation-bubbling.md"}'),p={name:"js/js-web-api/dom-events/propagation-bubbling.md"};function e(c,s,r,i,y,d){return l(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="_3-фаза-всплытия" tabindex="-1">3. Фаза всплытия <a class="header-anchor" href="#_3-фаза-всплытия" aria-label="Permalink to &quot;3. Фаза всплытия&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Всплытие</strong> - когда на элементе происходит событие, обработчики сначала срабатывают на нём, потом на его родителе, затем выше и так далее, вверх по цепочке предков</li></ul></div><ul><li>События «всплывают» от внутреннего элемента вверх через родителей подобно тому, как всплывает пузырёк воздуха в воде</li><li>Всплытие идёт с «целевого» элемента наверх. По умолчанию событие будет всплывать до элемента html, а затем до объекта document, а иногда даже до window, вызывая все обработчики на своём пути</li></ul><h3 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h3><div class="language-html"><button title="Скопировать код" class="copy"></button><span class="lang">html</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">&lt;!-- 3 вложенных элемента FORM &gt; DIV &gt; P с обработчиком на каждом --&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">form</span><span style="color:#986801;"> onclick</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;form&#39;</span><span style="color:#383A42;">)</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  FORM</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">div</span><span style="color:#986801;"> onclick</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;div&#39;</span><span style="color:#383A42;">)</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">    DIV</span></span>
<span class="line"><span style="color:#383A42;">    &lt;</span><span style="color:#E45649;">p</span><span style="color:#986801;"> onclick</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;p&#39;</span><span style="color:#383A42;">)</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">&gt;P&lt;/</span><span style="color:#E45649;">p</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;/</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">form</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><p><strong>Клик на <code>&lt;p&gt;</code> вызовет обработчик onclick</strong></p><ol><li>Сначала на самом <code>&lt;p&gt;</code></li><li>Потом на внешнем <code>&lt;div&gt;</code></li><li>Затем на внешнем <code>&lt;form&gt;</code></li><li>И так далее вверх по цепочке до самого <em>document</em></li></ol><h3 id="схема" tabindex="-1">Схема <a class="header-anchor" href="#схема" aria-label="Permalink to &quot;Схема&quot;">​</a></h3><img src="`+t+`" style="width:350px;"><h2 id="event-target" tabindex="-1">event.target <a class="header-anchor" href="#event-target" aria-label="Permalink to &quot;event.target&quot;">​</a></h2><ul><li>Всегда можно узнать, на каком конкретно элементе произошло событие</li><li>Самый глубокий элемент, который вызывает событие, называется <em>целевым элементом</em> - он доступен через <code>event.target</code></li></ul><h3 id="отличие-event-target-от-this" tabindex="-1">Отличие event.target от this <a class="header-anchor" href="#отличие-event-target-от-this" aria-label="Permalink to &quot;Отличие event.target от this&quot;">​</a></h3><ul><li><code>event.target</code> – это «целевой» элемент, на котором произошло событие, в процессе всплытия он неизменен</li><li><code>this</code> – это «текущий» элемент, до которого дошло всплытие, на нём сейчас выполняется обработчик</li><li>Возможна и ситуация, когда <code>event.target</code> и <code>this</code> – один и тот же элемент, например, если клик был непосредственно на самом элементе form, не на его подэлементе</li></ul><h3 id="пример-1" tabindex="-1">Пример <a class="header-anchor" href="#пример-1" aria-label="Permalink to &quot;Пример&quot;">​</a></h3><ul><li>Если стоит только один обработчик <em>form.onclick</em>, то он «поймает» все клики внутри формы. Где бы ни был клик внутри - он всплывёт до элемента <em>form</em>, на котором сработает обработчик</li></ul><div class="language-html"><button title="Скопировать код" class="copy"></button><span class="lang">html</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">form</span><span style="color:#986801;"> id</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;form&quot;</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  FORM</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">    DIV</span></span>
<span class="line"><span style="color:#383A42;">    &lt;</span><span style="color:#E45649;">p</span><span style="color:#383A42;">&gt;P&lt;/</span><span style="color:#E45649;">p</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;/</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">form</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">script</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  form.</span><span style="color:#4078F2;">onclick</span><span style="color:#0184BC;"> =</span><span style="color:#A626A4;"> function</span><span style="color:#383A42;"> (event) {</span></span>
<span class="line"><span style="color:#383A42;">    event.</span><span style="color:#E45649;">target</span><span style="color:#383A42;">.</span><span style="color:#E45649;">style</span><span style="color:#383A42;">.</span><span style="color:#E45649;">backgroundColor</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> &quot;yellow&quot;</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#383A42;">    console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;event.target: &quot;</span><span style="color:#0184BC;"> +</span><span style="color:#383A42;"> event.</span><span style="color:#E45649;">target</span><span style="color:#383A42;">.</span><span style="color:#E45649;">tagName</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">    console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;this: &quot;</span><span style="color:#0184BC;"> +</span><span style="color:#E45649;"> this</span><span style="color:#383A42;">.</span><span style="color:#E45649;">tagName</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">  };</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">script</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h2 id="прекращение-всплытия" tabindex="-1">Прекращение всплытия <a class="header-anchor" href="#прекращение-всплытия" aria-label="Permalink to &quot;Прекращение всплытия&quot;">​</a></h2><ul><li>Всплытие идёт с «целевого» элемента наверх. Любой промежуточный обработчик может решить, что событие полностью обработано, и остановить всплытие</li><li>Если у элемента есть несколько обработчиков на одно событие, то даже при прекращении всплытия все они будут выполнены</li><li><strong>Недостаток</strong>: при использовании систем аналитики где необходимо учитывать все клики, события с <em>stopPropagation</em> не будут учитываться</li></ul><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>event.stopPropagation()</code></strong> - прекращение всплытия, но на текущем элементе все обработчики будут вызваны</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>event.stopImmediatePropagation()</code></strong> - прекращение всплытия и остановка обработки событий на текущем элементе</p></div><div class="language-html"><button title="Скопировать код" class="copy"></button><span class="lang">html</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">body</span><span style="color:#986801;"> onclick</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&#39;Сюда всплытие не дойдёт&#39;</span><span style="color:#383A42;">)</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">button</span><span style="color:#986801;"> onclick</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">event.</span><span style="color:#4078F2;">stopPropagation</span><span style="color:#383A42;">()</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">&gt;Кнопка&lt;/</span><span style="color:#E45649;">button</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">body</span><span style="color:#383A42;">&gt;</span></span></code></pre></div>`,22)])])}const u=a(p,[["render",e]]);export{g as __pageData,u as default};
